impl CoverageEvidence{pub fn new(evidence_id:impl Into<String>,requirement_id:impl Into<String>,source_certificate_sha256:impl Into<String>,observation_sha256:impl Into<String>)->Result<Self,AssuranceError>{let evidence_id=evidence_id.into();let requirement_id=requirement_id.into();let source_certificate_sha256=source_certificate_sha256.into();let observation_sha256=observation_sha256.into();validate_identifier(&evidence_id,"coverage evidence")?;validate_identifier(&requirement_id,"coverage requirement")?;validate_sha256(&source_certificate_sha256,"coverage source")?;validate_sha256(&observation_sha256,"coverage observation")?;let evidence_sha256=hash_serializable(&(&evidence_id,&requirement_id,&source_certificate_sha256,&observation_sha256))?;Ok(Self{evidence_id,requirement_id,source_certificate_sha256,observation_sha256,evidence_sha256})}pub fn verify(&self)->Result<(),AssuranceError>{let expected=hash_serializable(&(&self.evidence_id,&self.requirement_id,&self.source_certificate_sha256,&self.observation_sha256))?;if expected!=self.evidence_sha256{return Err(AssuranceError::ClosureDenied("coverage evidence digest".into()));}Ok(())}}
